package com.example.webapptemplate.shop;
import com.example.webapptemplate.authors.AuthorOperations;import java.util.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class ShopController {
 private final ShopService service;private final AuthorOperations users;public ShopController(ShopService service,AuthorOperations users){this.service=service;this.users=users;}
 @GetMapping("/shop") public String catalog(Model model){model.addAttribute("products",service.products());model.addAttribute("buyers",users.choices());if(!model.containsAttribute("cart"))model.addAttribute("cart",Map.of());return "shop/catalog";}
 @PostMapping("/shop/cart") public String editCart(@RequestParam Map<String,String> p,Model model){model.addAttribute("cart",p);return catalog(model);}
 @GetMapping("/shop/products/{id}") public String product(@PathVariable UUID id,Model model){model.addAttribute("product",service.product(id));return "shop/product";}
 @PostMapping("/shop/confirm") public String confirm(@RequestParam UUID user,@RequestParam Map<String,String> p,Model model){try{users.requireAuthor(user);var lines=service.preview(quantities(p));model.addAttribute("lines",lines);model.addAttribute("total",lines.stream().mapToLong(ShopService.Line::total).sum());model.addAttribute("buyer",users.author(user).orElseThrow());model.addAttribute("requestId",UUID.randomUUID());return "shop/confirm";}catch(IllegalArgumentException e){model.addAttribute("error",e.getMessage());model.addAttribute("cart",p);return catalog(model);}}
 @PostMapping("/shop/orders") @ResponseBody public org.springframework.http.ResponseEntity<?> order(@RequestParam UUID requestId,@RequestParam UUID user,@RequestParam Map<String,String> p){try{var prices=new HashMap<UUID,Long>();p.forEach((k,v)->{if(k.startsWith("price."))prices.put(UUID.fromString(k.substring(6)),Long.parseLong(v));});return org.springframework.http.ResponseEntity.ok(Map.of("redirect","/shop/orders/"+service.order(requestId,user,quantities(p),prices)));}catch(IllegalArgumentException e){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}catch(org.springframework.dao.DataAccessException e){return org.springframework.http.ResponseEntity.status(503).body(Map.of("error","注文結果を確認できませんでした。この画面のまま再試行してください。要求IDを維持して重複を防ぎます。"));}}
 @GetMapping("/shop/orders") public String orders(Model model){model.addAttribute("orders",service.orders());return "shop/orders";}
 @GetMapping("/shop/orders/{id}") public String detail(@PathVariable UUID id,Model model){model.addAttribute("order",service.detail(id));model.addAttribute("lines",service.items(id));return "shop/order";}
 @PostMapping("/shop/orders/{id}/cancel") public String cancel(@PathVariable UUID id){service.cancel(id);return "redirect:/shop/orders/"+id;}
 private Map<UUID,Integer> quantities(Map<String,String> p){var result=new HashMap<UUID,Integer>();p.forEach((k,v)->{if(k.startsWith("qty.")){int n=Integer.parseInt(v);if(n!=0)result.put(UUID.fromString(k.substring(4)),n);}});return result;}
}
